const PLANE_WIDTH = 3.2;
const PLANE_HEIGHT = 2.0;

export default function createCollectionCard1(config, ctx) {
  const { gsap: gsapNamed } = ctx.THREE;
  const group = new ctx.THREE.Group();

  // Extract visual tokens from spec
  const colors = {
