  // Load the texture atlas
  const atlasRegion = config.atlasRegion || DEFAULT_ATLAS_REGION;
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  texturePromise.then((tex) => {
    tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
    tex.minFilter = ctx.THREE.LinearMipmapLinearFilter;
    tex.magFilter = ctx.THREE.LinearFilter;
    tex.generateMipmaps = true;

    // Crop to atlas region using UV offset/scale
    const atlasX = atlasRegion.x / tex.image.width;
    const atlasY = atlasRegion.y / tex.image.height;
    const atlasW = atlasRegion.width / tex.image.width;
    const atlasH = atlasRegion.height / tex.image.height;

    tex.repeat.set(atlasW, atlasH);
    tex.offset.set(atlasX, atlasY);

    material.map = tex;
    material.needsUpdate = true;
  });

  // Add a subtle gradient surface effect (no grain for static composition)
  const gradientUniform = uniform(0);
