    return vec3(grad);
  });

  // Apply gradient as overlay via color mixing (since we can't easily blend without custom)
  material.colorNode = gradientNode();

  // Add a very subtle border edge for definition
  const borderMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.15,
    side: ctx.THREE.DoubleSide,
    depthWrite: false
  });

