  const border = new ctx.THREE.Mesh(borderGeo, borderMaterial);
  border.position.z = 0.001;
  group.add(border);

  // Handle scene placement via userData (adapter applies outer position)
  group.position.set(
    config.scenePosition?.x ?? -3.2,
    config.scenePosition?.y ?? -0.3,
    config.scenePosition?.z ?? 0
  );
  group.rotation.set(
    config.scenePosition?.rotationX ?? 0,
    config.scenePosition?.rotationY ?? 0,
    config.scenePosition?.rotationZ ?? 0
  );
  group.scale.set(
