    config.scenePosition?.scaleY ?? 1,
    config.scenePosition?.scaleZ ?? 1
  );

  // No primitives to apply per spec
  const primitives = [];

  // Event handlers (none for static card)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    borderMaterial.dispose();
    borderGeo.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  return group;
}
